/** Integration DTOs: map onto existing project/source/scrap records, do not create a parallel store. */
export type Revision = string;
export type EvidenceKind = 'text' | 'ocr' | 'image-region' | 'video-frame' | 'subtitle' | 'audio';
export type TextSelector = { kind: 'text'; blockId: string; quote: string; prefix: string; suffix: string; offset: number; textProjectionVersion: number };
export type RegionSelector = { kind: 'region'; pageIndex?: number; box: [number, number, number, number]; originalWidth: number; originalHeight: number; rotation: 0 | 90 | 180 | 270 };
export type TimeSelector = { kind: 'time'; startMs: number; endMs: number; cueIds: string[]; frameRefs: string[] };
export interface PassageRef { id: string; sourceId: string; revision: Revision; selectors: Array<TextSelector | RegionSelector | TimeSelector>; evidenceKind: EvidenceKind; extractionMethod: string; match: 'exact' | 'context' | 'ambiguous' | 'lost' | 'partial' | 'captured-version'; }
export interface SourceSnapshot { id: string; revision: Revision; contentHash: string; capturedAt: string; title: string; origin: { type: 'url' | 'file' | 'archive' | 'media'; locator: string }; distribution: 'unknown' | 'excerpt-only' | 'authorized-full' | 'own-work'; contentRef: string; projectId: string; }
export interface ReadingMessage { id: string; role: 'user' | 'assistant'; content: string; evidenceIds: string[]; sourceRevision: Revision; state: 'queued' | 'generating' | 'complete' | 'failed' | 'cancelled'; interpretation: 'source-explanation' | 'inference' | 'hypothesis' | 'user-note'; }
export interface ReadingThread { id: string; artifactKind: 'reading-thread'; projectId: string; branchId: string; anchorRefs: PassageRef[]; messages: ReadingMessage[]; acceptedMessageIds: string[]; openQuestionIds: string[]; sourceRevisions: Record<string, Revision>; revision: number; durability: 'session-candidate' | 'user-saved'; }
export interface ReadingScrapExtension { readingThreadId?: string; originalPassageRefs: PassageRef[]; userNote?: string; adoptedInterpretationIds?: string[]; relations?: ReadingRelation[]; adoptedAt?: string; }
export interface ReadingRelation { id: string; from: PassageRef; to: PassageRef; type: 'explains' | 'qualifies' | 'contrasts' | 'same-upstream-source' | 'analogy'; reason: string; status: 'proposed' | 'accepted' | 'withdrawn'; acceptedByUserAt?: string; }
export interface ReadingViewState { sourceId: string; revision: Revision; topBlockId: string; offsetInBlock: number; selectionRefs: PassageRef[]; openedThreadId?: string; paper: 'theme' | 'warm' | 'dark'; typography: { fontRole: 'serif' | 'sans'; sizePx: number; lineHeight: number; columnEm: number }; readBoundary?: { blockOrder?: number; timeMs?: number }; }
export interface ReadingContextPacket { projectId: string; threadId: string; branchId: string; sourceRevisions: Record<string, Revision>; requestedAnchorRefs: PassageRef[]; allowedEvidence: PassageRef[]; userMessageId: string; operationId: string; budget: { effectiveContext: number; inputEstimate: number; outputReserve: number; accounting: 'provider' | 'tokenizer' | 'estimate' }; readBoundary?: ReadingViewState['readBoundary']; knowledgeHints: string[]; externalSourcesExplicitlySelected: string[]; purpose: 'explain' | 'translate' | 'compare' | 'locate' | 'brief' | 'review-understanding'; }
export interface CompactionRecord { version: 1; kind: 'conversation-compaction'; id: string; projectId: string; chatId: string; branchId: string; throughMessageId: string; firstKeptMessageId: string; coveredHash: string; prefixVersion: string; contextEpoch: number; providerScope: string; model: string; servedModel?: string; text: string; pins: Array<{messageId: string; text: string}>; readingRefs: PassageRef[]; openQuestionIds: string[]; createdAt: string; }
